const inputItems = $input.all();

function esc(v) {
  return String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function fmt(v) {
  return v === null || v === undefined || v === '' ? 'N/A' : esc(v);
}

function fmtNum(v, decimals = 1) {
  const n = Number(v);
  return Number.isFinite(n) ? n.toFixed(decimals) : 'N/A';
}

let rows = [];

// Case 1: HTTP node returned one item containing an array
if (inputItems.length === 1 && Array.isArray(inputItems[0].json)) {
  rows = inputItems[0].json;
}

// Case 2: HTTP node returned array inside a field
else if (inputItems.length === 1) {
  const j = inputItems[0].json;

  if (Array.isArray(j.body)) rows = j.body;
  else if (Array.isArray(j.data)) rows = j.data;
  else if (Array.isArray(j.result)) rows = j.result;
  else if (Array.isArray(j.results)) rows = j.results;
  else rows = [j];
}

// Case 3: HTTP node returned one row per item
else {
  rows = inputItems.map(i => i.json);
}

rows = rows.filter(r => r && r.run_date_sgt && r.ticker);

if (!rows.length) {
  return [{
    json: {
      alert_triggered: false,
      subject: 'AI Bubble Risk Alert - No Data',
      message: 'No AI stock scores found. Check the Get AI Scores node output shape.'
    }
  }];
}

rows.sort((a, b) => {
  const dateCompare = String(b.run_date_sgt).localeCompare(String(a.run_date_sgt));
  if (dateCompare !== 0) return dateCompare;
  return Number(b.overall_ai_risk_score) - Number(a.overall_ai_risk_score);
});

const latestDate = rows[0].run_date_sgt;
const latestRows = rows.filter(r => r.run_date_sgt === latestDate);

const threshold = 75;

const alertRows = latestRows
  .filter(r => Number(r.overall_ai_risk_score) >= threshold)
  .sort((a, b) => Number(b.overall_ai_risk_score) - Number(a.overall_ai_risk_score));

if (!alertRows.length) {
  const topRows = latestRows
    .sort((a, b) => Number(b.overall_ai_risk_score) - Number(a.overall_ai_risk_score))
    .slice(0, 5);

  return [{
    json: {
      alert_triggered: false,
      subject: `AI Risk Alert - No Trigger - ${latestDate}`,
      message:
        `🟢 <b>No AI Risk Alert Triggered</b>\n\n` +
        `<b>Date:</b> ${esc(latestDate)}\n` +
        `<b>Threshold:</b> ${threshold}/100\n\n` +
        `<b>Top AI Risk Scores</b>\n` +
        topRows.map(r =>
          `• <b>${esc(r.ticker)}</b>: ${fmtNum(r.overall_ai_risk_score)}/100 — ${fmt(r.signal_label)}`
        ).join('\n')
    }
  }];
}

const top = alertRows[0];

const lines = alertRows.map(r =>
  `• <b>${esc(r.ticker)}</b>: ${fmtNum(r.overall_ai_risk_score)}/100 — ${fmt(r.signal_label)}`
);

const explanations = alertRows.slice(0, 5).map(r =>
  `\n<b>${esc(r.ticker)}</b>\n${fmt(r.explanation || 'No explanation available.')}`
);

return [{
  json: {
    alert_triggered: true,
    subject: `AI Risk Alert - ${latestDate}`,
    message:
      `🔴 <b>AI Risk Alert</b>\n\n` +
      `<b>Date:</b> ${esc(latestDate)}\n` +
      `<b>Threshold:</b> ${threshold}/100\n` +
      `<b>Highest Risk:</b> ${esc(top.ticker)} — ${fmtNum(top.overall_ai_risk_score)}/100\n` +
      `<b>Stocks Triggered:</b> ${alertRows.length}\n\n` +
      `<b>Triggered Names</b>\n${lines.join('\n')}\n\n` +
      `<b>Top Explanations</b>\n${explanations.join('\n')}\n\n` +
      `<b>Suggested Action:</b> Review position sizing, valuation assumptions, and AI momentum exposure.`
  }
}];
